package com.cardcombat;import java.util.*;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.scheduler.BukkitRunnable;
public final class RitualManager{private final CardCombatPlugin p;private final Set<UUID>active=new HashSet<UUID>();public RitualManager(CardCombatPlugin p){this.p=p;}public boolean isActive(){return !active.isEmpty();}public boolean start(Player a,Player b,String card){if(a.equals(b)||active.contains(a.getUniqueId())||active.contains(b.getUniqueId()))return false;if(!p.isBattleMode(a)||!p.isBattleMode(b)||p.challenges().isInMatch(a.getUniqueId())||p.challenges().isInMatch(b.getUniqueId()))return false;active.add(a.getUniqueId());active.add(b.getUniqueId());Location c=a.getLocation().clone();new BukkitRunnable(){public void run(){active.remove(a.getUniqueId());active.remove(b.getUniqueId());if(a.isOnline())a.sendMessage(ChatColor.GOLD+"Ritual complete.");if(b.isOnline())b.sendMessage(ChatColor.GOLD+"Ritual complete.");}}.runTaskLater(p,20L*p.getConfig().getInt("settings.rituals.duration-seconds",5));return true;}public void shutdown(){active.clear();}}
